-- A GIN entry is a one-part tuple against `GinMaxItemSize`, 2 712: a 2 700-character
-- array element holds, and the containment probe finds it.
-- @setup
CREATE TABLE g (a text[]);
CREATE INDEX g_i ON g USING gin (a);
INSERT INTO g VALUES (ARRAY['']);
-- @test
-- @profile-lock
SELECT count(*) FROM g WHERE a @> ARRAY[''];
